script:
frappe.ui.form.on('QA Checklist', {
    checklist_template: function(frm) {
        if (frm.doc.checklist_template) {

            // 1. Set today's date if empty
            if (!frm.doc.date) {
                frm.set_value('date', frappe.datetime.get_today());
            }

            // 2. Fetch the items from the selected Template
            frappe.db.get_doc('QA Checklist Template', frm.doc.checklist_template)
                .then(template_doc => {
                    frm.clear_table('checklist_items');

                    (template_doc.template_items || template_doc.checklist_items || []).forEach(item => {
                        let row = frm.add_child('checklist_items');
                        row.test_case_id = item.test_case_id;
                        row.test_description = item.test_description;
                        row.expected_result = item.expected_result;
                        row.status = "Pending";
                    });

                    frm.refresh_field('checklist_items');
                    frm.dirty(); 
                });
        }
    }
});

frappe.ui.form.on('QA Checklist Item', {
    checklist_items_add: function(frm, cdt, cdn) {
        // Grab the prefix directly from the template field 
        let prefix = (frm.doc.checklist_template || "tc").toUpperCase();
        let last_id = 0;

        // Loop through rows to find the highest number after the hyphen
        (frm.doc.checklist_items || []).forEach(d => {
            if (d.name !== cdn && d.test_case_id && d.test_case_id.includes('-')) {
                let parts = d.test_case_id.split('-');
                let num = parseInt(parts[parts.length - 1]); 
                if (!isNaN(num) && num > last_id) last_id = num;
            }
        });

        // Format as TemplateName-ConsecutiveNumber
        const next_num = String(last_id + 1).padStart(3, '0');
        const next_id = `${prefix}-${next_num}`;

        frappe.model.set_value(cdt, cdn, 'test_case_id', next_id);
    }
});
